impl ManagedLocalAiStudio {
    pub(crate) fn new(
        root: PathBuf,
        environment: ManagedExecutionEnvironment,
        model_id: String,
    ) -> Result<Self, String> {
        let runtime = ManagedLocalRuntime::open(root).map_err(|error| error.to_string())?;
        let setup_status = runtime.setup_status(environment);
        let additional_storage_bytes = if model_id.trim().is_empty() {
            None
        } else {
            runtime
                .additional_storage_for_environment(&model_id, environment)
                .ok()
        };
        Ok(Self {
            runtime,
            environment,
            model_id,
            task: None,
            setup_status,
            additional_storage_bytes,
            status: None,
            confirm_remove_wsl: false,
            #[cfg(feature = "visual-validation")]
            visual_fixture: false,
        })
    }

    pub(crate) const fn environment(&self) -> ManagedExecutionEnvironment {
        self.environment
    }

    pub(crate) fn model_id(&self) -> &str {
        &self.model_id
    }

    pub(crate) fn capability_profile(&self) -> ModelCapabilityProfile {
        managed_model_capability_profile(&self.model_id)
    }

    pub(crate) fn selected_config(&self) -> Result<NativeModelConfig, String> {
        if self.model_id.trim().is_empty() {
            return Err("Register and select a managed GGUF model before starting inference.".to_owned());
        }
        if self.setup_status != ManagedSetupStatus::Ready {
            return Err("Complete managed Local AI runtime setup before starting inference.".to_owned());
        }
        if self.environment == ManagedExecutionEnvironment::Wsl2Linux
            && self.additional_storage_bytes != Some(0)
        {
            return Err(
                "Prepare the verified WSL2 model copy before starting inference.".to_owned(),
            );
        }
        self.runtime
            .configuration_for(&self.model_id, self.environment)
            .map(|config| NativeModelConfig::Managed(ManagedModelConfig { config }))
            .map_err(|error| error.to_string())
    }

    pub(crate) fn selected_inventory(&self) -> Option<InstalledModelInventory> {
        match self.selected_config().ok()? {
            NativeModelConfig::Managed(config) => Some(config.installed_inventory()),
            NativeModelConfig::Local(_) | NativeModelConfig::Hosted(_) => None,
        }
    }

    pub(crate) fn routing_candidates(&self) -> Vec<NativeModelConfig> {
        let Ok(models) = self.runtime.registered_models() else {
            return Vec::new();
        };
        models
            .into_iter()
            .filter(|model| model.model_id != self.model_id)
            .filter_map(|model| {
                self.runtime
                    .configuration_for(&model.model_id, self.environment)
                    .ok()
                    .map(|config| NativeModelConfig::Managed(ManagedModelConfig { config }))
            })
            .collect()
    }

    pub(crate) fn poll(&mut self, context: &egui::Context) {
        let Some(task) = self.task.as_ref() else {
            return;
        };
        let Some(result) = task.poll() else {
            context.request_repaint_after(std::time::Duration::from_millis(100));
            return;
        };
        self.task = None;
        match result {
            Ok(ManagedLocalTaskOutcome::RuntimeInstalled(installation)) => {
                self.status = Some(format!(
                    "Managed llama.cpp {} is verified and ready for {} (revision {}).",
                    installation.runtime_tag,
                    installation.environment.label(),
                    installation.runtime_revision,
                ));
            }
            Ok(ManagedLocalTaskOutcome::WslProvisioned) => {
                self.status = Some(
                    "Dedicated GameEngine-LocalAI WSL2 environment is provisioned. Runtime installation can continue."
                        .to_owned(),
                );
            }
            Ok(ManagedLocalTaskOutcome::RestartContinuationVerified) => {
                self.status = Some(
                    "Windows restart continuation was verified; Local AI setup can continue."
                        .to_owned(),
                );
            }
            Ok(ManagedLocalTaskOutcome::EnvironmentRemoved(environment)) => {
                self.status = Some(format!(
                    "Removed the GameEngine-managed {} runtime environment. Registered source GGUF files were not deleted.",
                    environment.label(),
                ));
                self.confirm_remove_wsl = false;
            }
            Ok(ManagedLocalTaskOutcome::ModelRegistered(model)) => {
                self.model_id = model.model_id;
                self.status = Some(format!(
                    "Registered GGUF `{}` with verified content identity {}.",
                    model.display_name,
                    short_digest(&model.content_sha256),
                ));
            }
            Ok(ManagedLocalTaskOutcome::ModelPrepared {
                model_id,
                environment,
            }) => {
                self.status = Some(format!(
                    "Prepared verified model {model_id} for {}.",
                    environment.label(),
                ));
            }
            Err(error) => {
                self.status = Some(format!(
                    "Managed Local AI setup failed at {}: {}",
                    error.layer().label(),
                    error,
                ));
            }
        }
        self.refresh_cached_state();
    }

    pub(crate) fn take_status(&mut self) -> Option<String> {
        self.status.take()
    }

}
